def paving_ways(n, drains):
    mod = 1_000_000_007
    blocked = [0] * n
    for r, c in drains:
        blocked[c] |= 1 << r

    def fill(row, full, nxt, out):
        if row == 3:
            out.append(nxt)
            return
        bit = 1 << row
        if full & bit:
            fill(row + 1, full, nxt, out)
            return
        fill(row + 1, full | bit, nxt | bit, out)
        if row < 2 and not full & (bit << 1):
            fill(row + 2, full | bit | (bit << 1), nxt, out)

    moves = []
    for full in range(8):
        out = []
        fill(0, full, 0, out)
        moves.append(out)

    ways = [1, 0, 0, 0, 0, 0, 0, 0]
    for c in range(n):
        new = [0] * 8
        b = blocked[c]
        for state in range(8):
            w = ways[state]
            if w and not state & b:
                for nxt in moves[state | b]:
                    new[nxt] += w
        ways = [x % mod for x in new]
    return ways[0]

